ALTER TABLE "dispatch_event_wakes" DROP CONSTRAINT "dispatch_event_wakes_action_valid";--> statement-breakpoint
ALTER TABLE "dispatch_event_wakes" DROP CONSTRAINT "dispatch_event_wakes_lifecycle_consistent";--> statement-breakpoint
ALTER TABLE "dispatch_event_wakes" ADD CONSTRAINT "dispatch_event_wakes_action_valid" CHECK ("dispatch_event_wakes"."action" IN ('CONTINUED', 'COMPLETED', 'CANCELLED'));--> statement-breakpoint
ALTER TABLE "dispatch_event_wakes" ADD CONSTRAINT "dispatch_event_wakes_lifecycle_consistent" CHECK (("dispatch_event_wakes"."action" = 'CONTINUED' AND "dispatch_event_wakes"."to_state" = 'QUEUED' AND "dispatch_event_wakes"."input_sequence" IS NOT NULL) OR ("dispatch_event_wakes"."action" = 'COMPLETED' AND "dispatch_event_wakes"."to_state" = 'COMPLETED' AND "dispatch_event_wakes"."input_sequence" IS NULL) OR ("dispatch_event_wakes"."action" = 'CANCELLED' AND "dispatch_event_wakes"."to_state" = 'CANCELLED' AND "dispatch_event_wakes"."input_sequence" IS NULL));
